export const QIANCHUAN_ACTIVE = QIANCHUAN_RECORDS.filter((r) => r.spend > 0);

export const QIANCHUAN_TOTALS = QIANCHUAN_RECORDS.reduce(
  (a, r) => ({
    balance: a.balance + r.balance,
    spend: a.spend + r.spend,
    orders: a.orders + r.orders,
    gmv: a.gmv + r.gmv,
    transfer: a.transfer + r.transfer,
  }),
  { balance: 0, spend: 0, orders: 0, gmv: 0, transfer: 0 },
);

/** 一级行业维度汇总（按消耗降序） */
export function qianchuanByIndustry() {
  const map = new Map<string, { industry: string; accounts: number; active: number; spend: number; orders: number; gmv: number }>();
  for (const r of QIANCHUAN_RECORDS) {
    const row = map.get(r.industry1) ?? { industry: r.industry1, accounts: 0, active: 0, spend: 0, orders: 0, gmv: 0 };
    row.accounts++;
    if (r.spend > 0) row.active++;
    row.spend += r.spend;
    row.orders += r.orders;
    row.gmv += r.gmv;
    map.set(r.industry1, row);
  }
  return [...map.values()].sort((a, b) => b.spend - a.spend);
}
